    private function listRead(array $in):array
    {
        self::keys($in,['date','status','page','dispatch']);$dispatch=$in['dispatch']??'';if(!is_string($dispatch)||!in_array($dispatch,['','all','upcoming','driver','return'],true))self::bad('Bộ lọc điều xe không hợp lệ.');$date=$in['date']??'';$status=$in['status']??'';if(!is_string($date)||!is_string($status))self::bad();if($date!=='')StaySchema::date($date);if($status!==''&&!in_array($status,self::STATES,true))self::bad();$page=$in['page']??'1';if(!is_string($page)||!preg_match('/^[1-9][0-9]{0,5}$/D',$page)||(int)$page>100000)self::bad();$where=[];$args=[];if($date!==''){$where[]='visit_date=?';$args[]=$date;}if($status!==''){$where[]='status=?';$args[]=$status;}$w=$where?' WHERE '.implode(' AND ',$where):'';$dispatchCounts=null;if($dispatch!==''){$now=time();$today=(new DateTimeImmutable('@'.$now))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d');$day=$this->query('SELECT id,code,visit_date,status,trip_id,data,version,created_at FROM jingo_ride_bookings WHERE visit_date=? ORDER BY created_at,id',[$today])->fetchAll(PDO::FETCH_ASSOC);foreach($day as &$r)$r['data']=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);unset($r);$groups=self::dispatchGroups($day,$now);$dispatchCounts=array_map('count',$groups);$matching=$groups[$dispatch];usort($matching,fn($a,$b)=>strcmp($a['data']['time']??'',$b['data']['time']??''));$total=count($matching);$rows=array_slice($matching,((int)$page-1)*50,50);}else{$total=(int)$this->query('SELECT COUNT(*) FROM jingo_ride_bookings'.$w,$args)->fetchColumn();$rows=$this->query('SELECT id,code,visit_date,status,trip_id,data,version,created_at FROM jingo_ride_bookings'.$w.' ORDER BY created_at DESC,id DESC LIMIT 50 OFFSET '.(((int)$page-1)*50),$args)->fetchAll(PDO::FETCH_ASSOC);}$qrReady=(new RidePayments($this->db))->available();foreach($rows as &$r){$r['data']=is_array($r['data'])?$r['data']:json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);unset($r['data']['requestHash']);$r['qrAvailable']=$qrReady&&RidePayments::eligible($r,$r['data'],true)&&!$this->query("SELECT bundle_id FROM jingo_checkout_members WHERE kind='rideId' AND entity_id=?",[$r['id']])->fetchColumn();$r['version']=(int)$r['version'];if(!empty($r['data']['autoPool'])){$pool=$this->pool($r['trip_id']);$r['pool']=$pool?['id'=>$pool['id'],'status'=>$pool['status'],'target'=>(int)$pool['target'],'total'=>(int)$pool['total'],'departure'=>$pool['departure'],'used'=>array_sum(array_map(fn($m)=>$m['data']['passengers'],$this->members($pool['id']))),'version'=>(int)$pool['version']]:null;}}return ['data'=>$rows,'total'=>$total,'page'=>(int)$page,'dispatchCounts'=>$dispatchCounts];
