    public static function dispatchGroups(array $rows,int $now):array
    {
        $today=(new DateTimeImmutable('@'.$now))->setTimezone(new DateTimeZone('Asia/Ho_Chi_Minh'))->format('Y-m-d');$day=array_values(array_filter($rows,fn($r)=>$r['visit_date']===$today));$active=array_filter($day,fn($r)=>!in_array($r['status'],['COMPLETED','CANCELLED'],true));return ['all'=>$day,'upcoming'=>array_values(array_filter($active,function($r)use($today,$now){if(!in_array($r['status'],['PENDING','WAITING_MATCH','MATCHED','WAITING_PICKUP'],true))return false;$clock=$r['data']['time']??'';if(!preg_match('/^(?:[01][0-9]|2[0-3]):[0-5][0-9]$/D',$clock))return false;$at=(new DateTimeImmutable($today.'T'.$clock.':00+07:00'))->getTimestamp();return $at>=$now&&$at<=$now+7200;})),'driver'=>array_values(array_filter($active,fn($r)=>!isset($r['data']['driver'])||preg_match('/^[\s\x{FEFF}]*$/u',$r['data']['driver']))),'return'=>array_values(array_filter($active,fn($r)=>!empty($r['data']['roundTrip'])&&empty($r['data']['returnTime'])))];
    }
    public function saveAgencyCost(string $id,array $in,string $actor):array
