        $id=self::uuid($id);self::keys($in,['version','agencyCost']);if(count($in)!==2||!array_key_exists('agencyCost',$in))self::bad();$version=self::num($in['version']??null,1,2147483646);$cost=$in['agencyCost']===null?null:self::num($in['agencyCost'],0,15000000000);return $this->transaction(function()use($id,$version,$cost,$actor){$r=$this->query('SELECT data,version FROM jingo_ride_bookings WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');if((int)$r['version']!==$version)throw new HttpError(409,'Đơn xe đã thay đổi. Tải lại trước khi lưu giá vốn.');$d=json_decode($r['data'],false,512,JSON_THROW_ON_ERROR);if(!$d instanceof stdClass)throw new HttpError(409,'Snapshot đơn xe không hợp lệ.');$d->agencyCost=$cost;$this->query('UPDATE jingo_ride_bookings SET data=?,version=version+1 WHERE id=?',[json_encode($d,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'ride.agency-cost.save',$id]);return ['agencyCost'=>$cost,'version'=>$version+1];});
    }
    public function update(string $id,array $in,string $actor):array
    {
        $id=self::uuid($id);self::keys($in,['version','status','tripId','driver','driverPhone','plate','operatorNote']);$version=self::num($in['version']??null,1,2147483646);$status=$in['status']??null;if(!in_array($status,self::STATES,true))self::bad();if(isset($in['tripId']))self::text($in['tripId'],0,80,false);$data=[];foreach(['driver'=>120,'driverPhone'=>25,'plate'=>30,'operatorNote'=>1000] as $k=>$max)$data[$k]=self::text($in[$k]??null,0,$max);
        return $this->transaction(function()use($id,$version,$status,$data,$actor,$in){$r=$this->query('SELECT * FROM jingo_ride_bookings WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$r)throw new HttpError(404,'Không tìm thấy đơn xe.');if((int)$r['version']!==$version)throw new HttpError(409,'Booking vừa thay đổi. Tải lại bảng.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);if(!empty($d['autoPool']))return $this->updateGroup($r,$d,$status,$data,$actor,$in['tripId']??null);if(($d['mode']??null)!=='PRIVATE')throw new HttpError(409,'Đơn ghép cũ cần chuyển dữ liệu trước khi xử lý.');if(($in['tripId']??null)!==null)self::bad('Xe riêng không gán chuyến ghép.');$next=['PENDING'=>['PENDING','WAITING_PICKUP','CANCELLED'],'WAITING_PICKUP'=>['WAITING_PICKUP','PICKED_UP','CANCELLED'],'PICKED_UP'=>['PICKED_UP','RUNNING','CANCELLED'],'RUNNING'=>['RUNNING','COMPLETED'],'COMPLETED'=>[],'CANCELLED'=>[]];if(!in_array($status,$next[$r['status']]??[],true))throw new HttpError(409,'Chuyển trạng thái không hợp lệ.');if(in_array($status,['WAITING_PICKUP','PICKED_UP','RUNNING'],true)&&($data['driver']===''||!preg_match('/^\+?[0-9 ()-]{8,25}$/D',$data['driverPhone'])||$data['plate']===''))self::bad('Cần tài xế, số điện thoại và biển số trước khi đón khách.');$this->query('UPDATE jingo_ride_bookings SET status=?,trip_id=NULL,data=?,version=version+1 WHERE id=?',[$status,json_encode(array_replace($d,$data),JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'ride.'.strtolower($status),$id]);return ['ok'=>true];});
